# Initialize output dataset
out = {'net_production': []}

# Step 1: Aggregate Production data by machine
prod_dict = {}
for row in sql_data.get('Production', []):
    machine = row.get('machine')
    qty = row.get('qty', 0) or 0
    if machine:
        if machine in prod_dict:
            prod_dict[machine] = prod_dict[machine] + qty
        else:
            prod_dict[machine] = qty
    else:
        continue # Skip NULL machine

# Step 2: Aggregate Scrap data by machine
scrap_dict = {}
for row in sql_data.get('Scrap', []):
    machine = row.get('machine')
    qty = row.get('qty', 0) or 0
    if machine:
        if machine in scrap_dict:
            scrap_dict[machine] = scrap_dict[machine] + qty
        else:
            scrap_dict[machine] = qty
    else:
        continue # Skip NULL machine

# Step 3: Calculate net production for machines present in Production
for machine, prod_qty in prod_dict.items():
    scrap_qty = scrap_dict.get(machine, 0)
    net_qty = prod_qty - scrap_qty
    out['net_production'].append({'machine': machine, 'net_qty': net_qty})
